let role=sessionStorage.getItem('presdodum.role')||'employee',current,previous='S05',selectedDoc='paquete',selectedRequest='SOL-1048',selectedPerson='PR-00271',provider='Dra. Elena Morales',requestContext='',mapMode='masters',mobile=false,notices=false;
