const screen=id=>screens.find(s=>s.id===id);
const url=id=>'#'+(screen(id)?.path||'/mapa');
const link=(id,text,cls='btn',ico='')=>`<a href="${url(id)}" data-go="${id}" class="${cls}">${ico?icon(ico):''}${text}</a>`;
const action=(name,text,cls='btn',ico='',extra='')=>`<button type="button" data-action="${name}" class="${cls}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const arrowLink=(id,text)=>link(id,text,'text-link','arrow');
const brand=()=>`<div class="brand"><span class="brandmark">${icon('plus')}</span>PRESDODUM</div>`;
const head=(title,subtitle,actions='',eyebrow='TU SALUD, EN UN SOLO LUGAR')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const tabs=(items,active)=>`<nav class="tabs" aria-label="Secciones de ${h(current?.module||'contenido')}">${items.map(([id,text])=>link(id,text,id===active?'active':'')).join('')}</nav>`;
