const empty=(title,sub,cta='')=>`<div class="empty">${icon('search')}<h3>${title}</h3><p>${sub}</p>${cta}</div>`;
const toolbar=(placeholder,filters='')=>`<div class="table-toolbar">${search(placeholder)}<div class="row gap8 wrap">${filters}</div></div>`;
const field=(label,name,value='',type='text',options='')=>`<label class="field ${options.includes('wide')?'wide':''}">${label}<input name="${name}" type="${type}" value="${h(value)}" ${options.replace('wide','')}></label>`;
const fieldSelect=(label,name,values,value='',required=true)=>`<label class="field">${label}<select name="${name}" ${required?'required':''}>${values.map(v=>`<option ${v===value?'selected':''}>${h(v)}</option>`).join('')}</select></label>`;
const textarea=(label,name,placeholder='',required=false)=>`<label class="field wide">${label}<textarea name="${name}" placeholder="${placeholder}" ${required?'required':''}></textarea></label>`;
const checkList=items=>`<ul class="check-list">${items.map(x=>`<li>${icon('check')}<span>${x}</span></li>`).join('')}</ul>`;
const art=()=>`<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 240 270" fill="none"><circle cx="145" cy="140" r="103" stroke="currentColor" opacity=".2"/><circle cx="145" cy="140" r="80" stroke="currentColor" opacity=".2"/><path d="M143 228s-74-43-74-96c0-36 45-53 74-18 29-35 74-18 74 18 0 53-74 96-74 96Z" fill="currentColor" opacity=".17"/><path d="M76 163h40l13-28 19 54 16-35h47" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><rect x="172" y="47" width="49" height="49" rx="16" fill="white" opacity=".7" transform="rotate(10 172 47)"/><path d="M193 62v22m-11-11h22" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><circle cx="49" cy="95" r="6" fill="currentColor" opacity=".3"/><circle cx="212" cy="222" r="9" stroke="currentColor" opacity=".4"/><path d="m61 232 5-11m-8 3 11 5" stroke="currentColor" stroke-width="2"/></svg></div>`;
