const navEmployee=[['S05','Inicio','home'],['S06','Mi salud','heart'],['S17','Beneficios','benefit'],['S12','Consultas médicas','calendar'],['S28','Coberturas','shield'],['S31','Solicitudes','clipboard'],['S33','Documentos','file'],['S35','NOM-035','leaf'],['S38','Mi perfil','user']];
const navCompany=[['S42','Inicio','home'],['S43','Colaboradores','users'],['S47','Medicina laboral','stethoscope'],['S49','Solicitudes','clipboard'],['S51','Reportes','chart'],['S33','Documentos','file'],['S52','NOM-035','leaf'],['S53','Configuración','settings']];
function navActive(id){const groups={S06:['M03','M04','M06'],S17:['M07','M08','M09'],S12:['M05'],S28:['M11','M12'],S31:['M13','M14','M10'],S35:['M16'],S38:['M17'],S43:['M20','M21'],S47:['M22'],S49:['M23'],S51:['M24'],S53:['M25']};if(id==='S51'&&current?.id==='S52')return false;if(id==='S52')return current?.id==='S52';return current?.id===id||(groups[id]||[]).includes(current?.m)}
function shell(body){const company=role==='company';const nav=company?navCompany:navEmployee;const user=company?'Paola Navarro':state.profile.name;return `<aside class="sidebar ${mobile?'open':''}" aria-label="Navegación principal">${brand()}<div class="brand-sub">SALUD INTEGRAL</div><div class="side-label">${company?'TU ORGANIZACIÓN':'TU BIENESTAR'}</div><nav class="nav">${nav.map(([id,label,ico])=>`<a href="${url(id)}" data-go="${id}" class="${navActive(id)?'active':''}" ${navActive(id)?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id===(company?'S49':'S31')?`<span class="nav-count">${(company?state.requests:myRequests()).filter(r=>r.status!=='Completada').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><a href="${url('S40')}" data-go="S40" class="${current?.m==='M18'?'active':''}">${icon('help')}<span>Ayuda</span></a></nav><div class="support-box mt16"><div class="row gap8">${icon('spark')}<h4>Estamos para ayudarte</h4></div><p>Encuentra respuestas y orientación en un solo lugar.</p>${link('S40','Ir al centro de ayuda','text-link','arrow')}</div><a href="#/mapa" class="map-link">${icon('map')}Mapa del producto<span class="token">55</span></a><div class="side-user row">${avatar(company?'PN':'ML',company?'purple':'pink')}<div><h4 style="font-size:11px">${h(company?'Paola Navarro':state.profile.first)}</h4><div class="tiny muted">${company?'Administración · Empresa':'Mi cuenta personal'}</div></div><button class="icon-btn" data-go="S01" title="Ir al acceso" aria-label="Ir al acceso">${icon('logout')}</button></div></div></aside><div class="main-shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menú de navegación">${icon('menu')}</button><div class="breadcrumb"><span class="home-crumb">${company?'Portal empresa':'Portal empleado'}</span>${icon('chevron')}<strong>${h(current?.module||'Mapa del producto')}</strong></div><div class="top-actions"><span class="demo-chip">DEMOSTRACIÓN · DATOS FICTICIOS</span><button class="icon-btn notification-trigger" data-action="notifications" aria-label="Ver notificaciones">${icon('bell')}<span class="notification-dot"></span></button><details class="portal-menu"><summary aria-label="Cambiar portal">${icon(company?'building':'user')}<span>${company?'Portal empresa':'Portal empleado'}</span><span class="portal-short">${company?'Empresa':'Empleado'}</span>${icon('down')}</summary><div class="dropdown"><button data-portal="employee">${icon('user')}Portal del empleado</button><button data-portal="company">${icon('building')}Portal de empresa</button><button data-go="S01">${icon('logout')}Pantalla de acceso</button></div></details>${avatar(company?'PN':'ML',company?'purple':'pink')}</div></header><main class="content" id="content" tabindex="-1">${body}</main><footer class="footer"><span>© 2026 PRESDODUM · Tu salud, en un solo lugar.</span><span class="row gap8">${icon('shield')}Entorno de demostración con información ficticia <span class="route-state">${current?.id||'Mapa'}${current?' · '+current.m:''}</span></span></footer></div><button class="float-assistant" data-action="assistant" aria-label="Abrir asistente PRESDODUM con IA">${icon('spark')}<span>Asistente PRESDODUM<small>Estamos contigo</small></span></button>${notices?notificationsPanel():''}`}
function notificationsPanel(){const company=role==='company';const notices=company?[
...(state.notifications.requests?[['S49','Solicitudes de colaboradores','Revisa la bandeja de atención.','clipboard','orange']]:[]),
...(state.notifications.documents?[['S47','Medicina laboral','Consulta el estado de las autorizaciones.','lock','green']]:[]),
...(state.notifications.summary?[['S52','Bienestar laboral','Consulta la participación agregada de ejemplo.','leaf','purple']]:[])
]:[['S12','Tu próxima consulta','Revisa tu agenda de demostración.','calendar','blue'],['S32','Tu solicitud tiene seguimiento','Consulta el avance de tus solicitudes.','clipboard','orange'],['S35','Tu bienestar también cuenta','Explora el centro NOM-035.','leaf','purple']];return `<div class="notifications-pop"><div class="between" style="padding-right:16px"><h3>Notificaciones</h3>${action('notifications',icon('close'),'icon-btn','','aria-label="Cerrar notificaciones"')}</div>${notices.map(([id,t,d,i,c])=>`<a class="list-item" href="${url(id)}" data-go="${id}">${iconbox(i,c)}<div><h4>${t}</h4><p>${d}</p></div></a>`).join('')||'<p class="pad small muted">No hay avisos activos con tus preferencias actuales.</p>'}</div>`}
function appointmentCard(){const a=state.appointments.find(a=>a.status==='Confirmada');return `<div class="card appointment"><div class="appointment-title"><h3>Tu próxima consulta</h3>${icon('calendar')}</div>${a?`<div class="row">${avatar('EM','blue','lg')}<div><div class="doctor-title">${h(a.doctor)}</div><p>${h(a.specialty)} · ${h(a.mode)}</p></div></div><div class="appointment-date"><div class="date-square"><small>${new Date(a.date+'T12:00:00').toLocaleDateString('es-MX',{month:'short'}).toUpperCase()}</small><strong>${a.date.slice(-2)}</strong></div><div><h4>${formatDate(a.date)}</h4><p>${h(a.time)} h · ${a.status}</p></div></div>${link('S12','Ver mi consulta','btn secondary full','arrow')}`:`<div class="muted small">Tienes espacio para cuidarte. Programa tu siguiente consulta.</div>${link('S14','Agendar consulta','btn secondary full','calendar')}`}</div>`}
const formatDate=d=>new Date(d+'T12:00:00').toLocaleDateString('es-MX',{day:'numeric',month:'long',year:'numeric'});
function benefitCard(b){return `<a class="card benefit-card" href="${url(b.route)}" data-go="${b.route}">${iconbox(b.icon,b.color)}<div class="overline">${b.title}</div><h3>${b.name}</h3><p>${b.desc}</p><span class="text-link">Conocer beneficio ${icon('arrow')}</span></a>`}
function dashboard(){return head(`Hola, ${h(state.profile.first)} <span style="color:#a7b39e;font-size:25px;font-weight:400">☀</span>`,'Cuidarte es más fácil cuando todo está en un solo lugar.',link('S33','Mi paquete de salud','btn secondary','file'))+`<div class="wide-narrow dashboard-top"><section class="card hero"><div class="hero-copy"><span class="hero-label">${icon('shield')}PAQUETE INTEGRAL DE SALUD ${badge('Activo')}</span><h2>Tu bienestar.<br>Una prioridad, todos los días.</h2><p>Conoce tu salud, aprovecha tus beneficios y encuentra el apoyo que necesitas.</p>${link('S06','Ver mi expediente','btn','arrow')}</div>${art()}</section>${appointmentCard()}</div><div class="quick-actions">${[['S24','Asesoría médica','Orientación cuando la necesitas','chat','blue'],['S19','Estudio preventivo','Un paso adelante en tu salud','heart','green'],['S26','Servicio de ambulancia','Conoce cómo solicitar asistencia','ambulance','orange']].map(([id,t,d,i,c])=>`<a class="quick-action" href="${url(id)}" data-go="${id}">${iconbox(i,c)}<div><h4>${t}</h4><p>${d}</p></div>${icon('chevron')}</a>`).join('')}</div>${section('Todo tu bienestar, en un lugar','Descubre lo que tu paquete tiene para ti.',arrowLink('S17','Ver todos los beneficios'))}<div class="grid3">${[benefitData[0],benefitData[1],benefitData[4]].map(benefitCard).join('')}</div><div class="wide-narrow mt24"><section class="card">${cardHead('Tus solicitudes','Estamos dando seguimiento a lo que necesitas.',arrowLink('S31','Ver todas'))}${myRequests().slice(0,2).map(r=>requestItem(r)).join('')}</section><section class="card">${cardHead('Tu ruta de bienestar')}<div class="health-steps"><div class="health-step"><span class="step-dot">${icon('check')}</span><div><h4>Tu paquete está activo</h4><p>Desde el 15 de enero de 2026.</p></div></div><div class="health-step"><span class="step-dot">2</span><div><h4>Agenda tu revisión anual</h4><p>Dedica un momento a tu prevención.</p>${arrowLink('S19','Conocer mi estudio')}</div></div></div></section></div>`}
function requestItem(r){return `<a class="list-item" href="${url(role==='company'?'S50':'S32')}" data-request="${h(r.id)}">${iconbox(r.type.includes('Estudio')?'flask':'chat',r.type.includes('Estudio')?'green':'blue')}<div><h4>${h(r.type)}</h4><p>${h(r.id)} · ${h(r.date)}</p></div><div class="end">${status(r.status)}</div>${icon('chevron','chev')}</a>`}
function health(id){
 const p=state.profile,t=tabs([['S06','Resumen del expediente'],['S07','Historia clínica'],['S08','Vacunas'],['S15','Medicación y recetas']],id);
 let body='';
 if(id==='S06')body=`<div class="profile-strip compact-profile">${avatar('ML','pink','lg')}<div><h2>${h(p.name)}</h2><p>Expediente ${h(p.id)} · ${h(p.package)}</p></div><div class="right">${badge('Activo')}</div></div><div class="grid2"><section class="card">${cardHead('Registro de información del usuario','Identificación y antecedentes del expediente personal.')}${data([['Nombre completo',h(p.name)],['Fecha de nacimiento','16 de abril de 1992'],['Grupo sanguíneo',h(p.blood)],['Alergias',h(p.allergies)],['Antecedentes personales','Sin antecedentes capturados · ejemplo',true],['Última actualización','08 de octubre de 2026'],['Empresa',h(p.company)]])}<div class="pad" style="padding-top:0">${badge('Datos ficticios','gray')}</div></section><section class="card">${cardHead('Funciones de mi expediente','Información conectada para dar continuidad a tu salud.')}${[['S07','Historia clínica completa','Consulta el historial de atenciones y estudios.','activity'],['S15','Seguimiento de medicación','Medicamentos y recetas vinculadas a tus consultas.','pill'],['S38','Acceso y seguridad de datos','Privacidad y autorización para medicina laboral.','lock']].map(([id,t,d,i])=>`<a class="list-item" href="${url(id)}" data-go="${id}">${iconbox(i)}<div><h4>${t}</h4><p>${d}</p></div>${icon('chevron','chev')}</a>`).join('')}<div class="list-item">${iconbox('chart','blue')}<div><h4>Informes y estadísticas personales</h4><p>4 registros de historia · 1 receta · 6 documentos de ejemplo</p><div class="mt8">${action('export-health','Generar informe personal','text-link','download')}</div></div></div></section></div>`;
 else if(id==='S07')body=`<div class="wide-narrow"><section class="card">${cardHead('Historia clínica','Expediente '+h(p.id)+' · '+h(p.name),badge('4 registros','gray'))}<div class="timeline">${[['08 OCT 2026','Consulta de medicina general','Revisión de bienestar · Dra. Elena Morales','S09','stethoscope','blue'],['08 OCT 2026','Estudio preventivo anual','Documento de ejemplo disponible','S11','flask','green'],['02 SEP 2026','Registro de vacunación','Registro ilustrativo de vacunación','S08','shield','purple'],['15 ENE 2026','Activación de tu paquete','Paquete Integral de Salud','S33','heart','pink']].map(([date,t,d,id,i,c])=>`<div class="timeline-item">${iconbox(i,c)}<div><time>${date}</time><h3 class="mt8">${t}</h3><p>${d}</p><div class="mt8">${arrowLink(id,'Ver detalle')}</div></div></div>`).join('')}</div></section><div class="stack"><div class="card pad"><h3>Tu expediente personalizado</h3><p class="muted small mt8">Consulta los registros, da seguimiento a tu medicación y genera tu informe de ejemplo.</p>${link('S06','Ver resumen del expediente','btn secondary mt24','clipboard')}</div>${info('Las notas clínicas privadas no están disponibles para el portal de empresa.')}</div></div>`;
 else body=`<div class="grid2"><section class="card">${cardHead('Mi registro de vacunas','Información ilustrativa del expediente.')}<div class="list-item">${iconbox('shield','purple')}<div><h3>Vacunación · registro de ejemplo</h3><p>02 sep 2026 · Centro de Salud Horizonte</p></div>${badge('Registrada')}</div><div class="pad">${info('El registro no constituye una recomendación ni un esquema de vacunación.')}</div></section><section class="card pad">${iconbox('benefit','purple','big')}<h2 class="mt16">Tu beneficio en vacunas</h2><p class="muted small mt8">Consulta las vacunas contempladas y solicita un descuento.</p>${link('S18','Conocer beneficio','btn mt24','arrow')}</section></div>`;
 return head('Expediente digital e historial clínico','Registro personalizado de salud, medicación y documentos.',link('S33','Ver documentos','btn secondary','file'))+t+body;
}
function clinical(id){const recipe=id==='S10',study=id==='S11';const title=recipe?'Receta de ejemplo':study?'Resultado de estudio':'Detalle de consulta';return link('S07','Volver a mi historial','back','arrow')+head(title,'Expediente PR-00271 · Mariana López Hernández',recipe?link('S34','Ver documento de receta','btn','file')+action('doc-download','Descargar receta','btn secondary','download','data-doc-id="receta"'):link(study?'S34':'S10',study?'Ver documento':'Ver receta','btn',study?'file':'arrow'))+`<div class="wide-narrow"><section class="card"><div class="detail-hero">${iconbox(recipe?'file':study?'flask':'stethoscope','blue','big')}<div>${badge(recipe?'Documento ilustrativo':'Registro disponible',recipe?'orange':'green')}<h2 class="mt8">${recipe?'REC-0082':study?'Estudio preventivo anual':'Consulta de medicina general'}</h2><p>08 de octubre de 2026 · Atención de ejemplo</p></div></div>${data([['Profesional','Dra. Elena Morales'],['Centro','Centro Médico Horizonte · ficticio'],['Modalidad',study?'Laboratorio':recipe?'Documento digital':'Presencial'],['Folio',recipe?'REC-0082':study?'EST-0113':'CON-0186'],['Motivo',study?'Revisión preventiva anual':'Seguimiento de bienestar',true],...(recipe?[['Estado de la receta','Generada y registrada · ejemplo',true]]:[])])}<div class="pad" style="padding-top:0"><h3>${recipe?'Contenido de demostración':study?'Sobre este resultado':'Notas de la atención'}</h3><p class="small muted mt8">${recipe?'Este archivo permite demostrar la consulta y descarga de una receta. No contiene una pauta de tratamiento y no es una prescripción válida.':study?'El documento es una muestra de organización del expediente. No incluye resultados de laboratorio reales ni interpretaciones médicas.':'Revisión general de bienestar. Se registra el seguimiento preventivo y la disponibilidad de documentos de ejemplo para el expediente.'}</p><div class="mt24">${info('Registro completamente ficticio. Su contenido no debe utilizarse para tomar decisiones médicas.','blue')}</div></div></section><div class="stack"><section class="card">${cardHead('Documentos relacionados')}${[['receta','Receta de ejemplo'],['resultado','Resultado preventivo']].map(([d,n])=>`<button class="list-item full" data-doc="${d}" style="text-align:left">${iconbox('file','blue')}<div><h4>${n}</h4><p>PDF · 08 oct 2026</p></div>${icon('chevron','chev')}</button>`).join('')}</section><section class="card pad"><h3>¿Necesitas orientación?</h3><p class="small muted mt8">Solicita una asesoría para conocer los servicios disponibles.</p>${link('S24','Solicitar asesoría','btn secondary full mt24','chat')}</section></div></div>`}
function consultations(id){const past=id==='S13';return head('Consultas médicas','Un espacio para dar continuidad a tu salud.',link('S14','Agendar consulta','btn','plus'))+tabs([['S12','Próximas consultas'],['S13','Consultas anteriores']],past?'S13':'S12')+`<div class="wide-narrow"><section class="card">${cardHead(past?'Tus atenciones anteriores':'Tu agenda',past?'Revisa la información de tus consultas.':'Consulta los detalles de tus próximas citas.')}${past?`<a class="list-item" href="${url('S09')}" data-go="S09">${avatar('EM','blue','lg')}<div><h3>Medicina general</h3><p>Dra. Elena Morales · 08 oct 2026</p></div><div class="end">${badge('Atendida')}<p>Ver detalle ${icon('chevron','chev')}</p></div></a>`:state.appointments.length?state.appointments.map(a=>`<div class="pad" style="border-bottom:1px solid var(--border)"><div class="between"><div class="row">${avatar('EM','blue','lg')}<div><h3>${h(a.specialty)}</h3><p class="small muted mt8">${h(a.doctor)} · ${h(a.mode)}</p></div></div>${status(a.status)}</div><div class="grid2 mt24"><div class="row small muted">${icon('calendar')}<span>${formatDate(a.date)}</span></div><div class="row small muted">${icon('clock')}<span>${h(a.time)} h · Hora CDMX</span></div></div>${a.status==='Confirmada'?`<div class="row mt24 wrap">${action('appointment-details','Ver indicaciones','btn secondary small','eye',`data-id="${h(a.id)}"`)}${action('cancel-appointment','Cancelar cita de ejemplo','btn ghost small','',`data-id="${h(a.id)}"`)}</div><div class="notice blue mt16" id="indications-${h(a.id)}" hidden>${icon('info')}<div>Tu cita de ejemplo es el ${formatDate(a.date)} a las ${h(a.time)} h, con ${h(a.doctor)}. Modalidad: ${h(a.mode)}.<br>Motivo: ${h(a.reason||'Revisión de bienestar')}.<br>Esta agenda no genera atención real ni enlace de conexión.</div></div>`:''}</div>`).join(''):empty('Tu agenda está libre','Programa una consulta cuando lo necesites.',link('S14','Agendar consulta','btn','calendar'))}</section><div class="stack"><section class="card pad">${iconbox('video','blue','big')}<h3 class="mt16">Cerca, incluso a distancia</h3><p class="small muted mt8">Elige una videoconsulta o una atención presencial con los prestadores de ejemplo.</p>${link('S22','Explorar red médica','text-link mt24','arrow')}</section>${info('Las citas se guardan en este navegador. No se contacta a un prestador real.')}</div></div>`}
function medications(id){return head('Medicamentos y recetas','Consulta los registros vinculados con tus atenciones.')+tabs([['S15','Mis medicamentos'],['S16','Mis recetas']],id)+`<div class="wide-narrow"><section class="card">${cardHead(id==='S15'?'Registro de medicamentos':'Recetas disponibles','Documentos ilustrativos de tu expediente.')}${id==='S15'?`<div class="pad"><div class="row">${iconbox('pill','orange','big')}<div><h3>Tratamiento de ejemplo</h3><p class="small muted mt8">Registro de demostración · REC-0082</p></div>${badge('Histórico','gray')}</div><p class="small muted mt24">El prototipo no contiene dosis ni instrucciones de consumo. Consulta el documento ilustrativo vinculado.</p>${link('S10','Ver receta vinculada','btn secondary mt24','file')}</div>`:`<div class="list-item">${iconbox('file','blue')}<div><h3>Receta de ejemplo · REC-0082</h3><p>08 oct 2026 · Dra. Elena Morales</p></div><div class="end">${link('S10','Abrir receta','text-link','arrow')}</div></div>`}</section><section class="card pad">${iconbox('benefit','orange','big')}<h2 class="mt16">Cuida tu salud y tu economía</h2><p class="small muted mt8">Descubre las opciones de descuentos en medicamentos de tu paquete.</p>${link('S20','Ver beneficio de farmacia','btn mt24','arrow')}</section></div>`}
function benefits(){return head('Tus beneficios','Un paquete que te acompaña en cada etapa de tu bienestar.',link('S22','Explorar red médica','btn secondary','pin'))+`<div class="notice mb16">${icon('shield')}<div><strong>Paquete Integral de Salud · Activo</strong><br>Los alcances, prestadores y descuentos que ves en esta demostración son ilustrativos.</div></div><div class="grid3 mt24">${benefitData.map(benefitCard).join('')}</div>${section('También cuentas con protección','Conoce tus coberturas y los pasos para solicitar asistencia.',arrowLink('S28','Ver mis coberturas'))}<div class="grid3">${[['S29','Protección por accidentes','shield','green'],['S30','Asistencia en gastos funerarios','leaf','purple'],['S26','Servicio de ambulancia','ambulance','orange']].map(([id,t,i,c])=>`<a class="quick-action" href="${url(id)}" data-go="${id}">${iconbox(i,c)}<h4>${t}</h4>${icon('chevron')}</a>`).join('')}</div>`}
function benefitDetail(id){
 const map={S18:benefitData[1],S19:benefitData[0],S20:benefitData[4],S21:benefitData[3]},b=map[id],preventive=id==='S19',pharmacy=id==='S20',vaccines=id==='S18';
 const title=preventive?'1 estudio preventivo gratuito al año':pharmacy?'Desde 30% en 100 medicamentos':vaccines?'Solicita descuentos en vacunas':'Descuentos en estudios clínicos';
 const desc=preventive?'Para la prevención de enfermedades y complicaciones de salud.':pharmacy?'Consulta el beneficio aplicable al catálogo de medicamentos participantes.':vaccines?'Vacunas contempladas en tu Paquete Integral de Salud.':'Consulta los prestadores y sus tarifas preferenciales.';
 return link('S17','Volver a beneficios','back','arrow')+head(b.name,'Paquete Integral de Salud · Beneficios del trabajador.')+`<div class="wide-narrow"><section class="card"><div class="detail-hero">${iconbox(b.icon,b.color,'big')}<div>${badge(preventive?'Sin costo':pharmacy?'Desde 30%':'Beneficio disponible',b.color)}<h2 class="mt8">${title}</h2><p>${desc}</p></div></div><div class="pad"><h3>${vaccines?'Vacunas contempladas':'Cómo utilizar tu beneficio'}</h3><div class="mt24">${vaccines?`<div class="vaccine-grid">${packageTerms.vaccines.map(v=>`<div>${icon('shield')}<strong>${v}</strong></div>`).join('')}</div>`:checkList(preventive?['1 estudio gratuito por año.','Prevención de enfermedades y complicaciones de salud.','Selección de prestador y fecha preferida.','Resultados y documentos dentro de tu expediente.']:pharmacy?['100 medicamentos diferentes contemplados en el beneficio.','Descuentos desde el 30%.','Consulta de disponibilidad y condiciones por producto.','Solicitud de cupón a través del portal.']:['Descuentos en estudios clínicos.','Consulta la red de laboratorios y centros de diagnóstico.','Solicita orientación para coordinar tu atención.'])}</div><div class="mt24">${info(vaccines?'Consulta disponibilidad, precio final y condiciones con el prestador. La selección de una vacuna requiere orientación profesional.':'Demostración con datos ficticios. La atención y aplicación del beneficio se coordinan con el prestador.')}</div></div></section><div class="stack"><section class="card pad"><div class="mini-label">MI BENEFICIO</div><h2>${preventive?'Tu prevención, sin costo':pharmacy?'Medicamentos a tu alcance':'Descuentos en vacunación'}</h2><div class="details-list" style="padding:15px 0">${dlRow('Titular','Mariana López')}${dlRow('Estado',badge('Activo'))}${preventive?dlRow('Periodicidad','1 estudio al año')+dlRow('Costo para el trabajador','$0.00 MXN'):pharmacy?dlRow('Catálogo','100 medicamentos')+dlRow('Descuento','Desde 30%'):dlRow('Gestión','Solicitud de descuento')}</div>${pharmacy?action('coupon','Solicitar cupón de descuento','btn full','benefit'):link(preventive?'S25':vaccines?'S24':'S22',preventive?'Solicitar mi estudio gratuito':vaccines?'Solicitar descuento':'Explorar red de estudios','btn full','arrow')}<p class="tiny muted mt16">Paquete activo · Titular del beneficio</p></section><section class="card pad"><h3>Seguimiento desde el portal</h3><p class="small muted mt8">Cada solicitud tiene un folio para consultar su avance y los documentos relacionados.</p>${link('S31','Ver mis solicitudes','text-link mt24','arrow')}</section></div></div>`;
}
const providers=[{name:'Dra. Elena Morales',initials:'EM',specialty:'Medicina general',type:'Médicos',zone:'Centro',mode:'Presencial y en línea',color:'blue'},{name:'Dr. Andrés Castillo',initials:'AC',specialty:'Medicina interna',type:'Médicos',zone:'Sur',mode:'Presencial',color:'green'},{name:'Laboratorio Vida Clara',initials:'VC',specialty:'Laboratorio clínico',type:'Estudios',zone:'Centro',mode:'Presencial',color:'purple'},{name:'Centro Diagnóstico Alameda',initials:'DA',specialty:'Estudios de imagen',type:'Estudios',zone:'Norte',mode:'Presencial',color:'orange'},{name:'Dra. Fernanda Ríos',initials:'FR',specialty:'Nutrición y bienestar',type:'Médicos',zone:'Sur',mode:'En línea',color:'pink'}];
function network(id){const p=providers.find(p=>p.name===provider)||providers[0];if(id==='S23')return link('S22','Volver a la red médica','back','arrow')+head('Conoce a tu prestador','Atención dentro de la red de demostración.')+`<div class="wide-narrow"><section class="card"><div class="profile-strip" style="border:0;margin:0">${avatar(p.initials,p.color,'xl')}<div>${badge('Red de ejemplo','green')}<h2 class="mt8">${p.name}</h2><p>${p.specialty} · ${p.mode}</p></div></div>${data([['Servicio',p.specialty],['Zona','CDMX · '+p.zone],['Modalidad',p.mode],['Horarios','Lun–vie · 09:00 a 18:00'],['Ubicación','Sede '+p.zone+' · dirección ilustrativa',true]])}<div class="pad" style="padding-top:0">${info('Todos los prestadores y ubicaciones de esta red son ficticios.')}</div></section><section class="card pad"><h2>El siguiente paso es cuidarte</h2><p class="small muted mt8">${p.type==='Estudios'?'Solicita la coordinación de tu estudio con un prestador de ejemplo.':'Selecciona el día y horario de tu cita de ejemplo.'}</p><div class="details-list" style="padding:15px 0">${dlRow('Beneficio',badge('Tarifa preferencial'))}${dlRow('Paquete','Salud Integral')}${dlRow('Descuento','Según servicio y prestador')}</div>${link(p.type==='Estudios'?'S25':'S14',p.type==='Estudios'?'Solicitar estudio':'Agendar consulta','btn full','calendar')}<p class="tiny muted mt16">Las agendas y tarifas son ilustrativas.</p></section></div>`;return head('Descuentos en consultas y estudios','Consultas presenciales de primer contacto y estudios clínicos.',link('S24','Solicitar orientación','btn secondary','chat'))+info('Directorio de demostración. Profesionales, centros y ubicaciones ficticios.')+`<div class="card mt24">${toolbar('Buscar prestador o especialidad',select('Tipo de servicio',['Todos los servicios','Médicos','Estudios'],'data-filter="type"')+select('Zona',['Todas las zonas','Centro','Sur','Norte'],'data-filter="zone"'))}<div class="pad grid2" data-search-list>${providers.map(p=>`<article class="card pad" data-search-item data-search-text="${h(p.name+' '+p.specialty+' '+p.zone)}" data-type="${p.type}" data-zone="${p.zone}"><div class="row">${avatar(p.initials,p.color,'lg')}<div><h3>${p.name}</h3><p class="small muted mt8">${p.specialty}</p></div></div><div class="row small muted mt24">${icon('pin')}CDMX · Zona ${p.zone}</div><div class="row small muted mt8">${icon('video')}${p.mode}</div><div class="between mt24">${badge('Tarifa preferencial',p.color)}<button class="text-link" data-provider="${h(p.name)}">Ver perfil ${icon('arrow')}</button></div></article>`).join('')}</div><div class="empty-hint">No encontramos prestadores con esos filtros.</div></div>`}
function serviceAllowance(id){
 if(id==='S26')return `<section class="card pad allowance"><div class="mini-label">BENEFICIO DEL TRABAJADOR</div><div class="allowance-number">1</div><h2>Servicio de ambulancia</h2><p class="small muted mt8">1 servicio de ambulancia para el trabajador, conforme a las condiciones del paquete.</p><div class="mt16">${badge('Disponible · demostración')}</div></section>`;
 if(id==='S25')return `<section class="card pad allowance"><div class="mini-label">PREVENCIÓN ANUAL</div><div class="allowance-number">$0</div><h2>1 estudio gratuito al año</h2><p class="small muted mt8">Prevención de enfermedades y complicaciones de salud.</p></section>`;
 return `<section class="card pad allowance"><div class="mini-label">ASESORÍAS MÉDICAS INCLUIDAS</div><div class="allowance-number">10</div><h2>Asesorías gratuitas</h2><p class="small muted mt8">En línea o vía telefónica durante la vigencia del contrato.</p><div class="details-list" style="padding:10px 0">${dlRow('Modalidades','En línea / Telefónica')}${dlRow('Red de atención','Médicos y hospitales')}${dlRow('Referencia','Anexo 1')}</div>${link('S22','Consultar red de atención','text-link','arrow')}<p class="tiny muted mt16">Directorio de ejemplo. Anexo 1 original pendiente de integrar.</p></section>`;
}
function requestForm(id){const ambulance=id==='S26',preventive=id==='S25';const type=ambulance?'Servicio de ambulancia':preventive?'Estudio preventivo anual':requestContext||'Asesoría médica';if(id==='S27'){const r=request();return `<div class="success-wrap"><div class="success-icon">${icon('check')}</div><div class="eyebrow">SOLICITUD DE DEMOSTRACIÓN</div><h1>Tu solicitud quedó registrada</h1><p>Ya puedes consultar su avance desde Solicitudes. Todos los cambios se guardan en este navegador.</p><div class="card"><div class="request-identity">${iconbox('clipboard','green')}<div><div class="folio">FOLIO ${h(r.id)}</div><h2>${h(r.type)}</h2></div></div><div class="details-list">${dlRow('Estado',status(r.status))}${dlRow('Titular',h(r.owner))}${dlRow('Fecha',h(r.date))}${dlRow('Siguiente paso','Revisión de la coordinación')}</div></div><div class="actions">${link('S32','Dar seguimiento','btn','arrow')}${link('S05','Volver al inicio','btn secondary')}</div></div>`}return link(preventive?'S19':ambulance?'S28':'S31','Volver','back','arrow')+head(ambulance?'Servicio de ambulancia':preventive?'Tu estudio preventivo':'Solicitar asesoría médica',ambulance?'Conoce el flujo de asistencia mediante una simulación.':'Cuéntanos qué necesitas y demos el siguiente paso.')+`<div class="wide-narrow"><form class="card pad" data-form="request" data-request-type="${h(type)}"><h2>${ambulance?'Simular solicitud de asistencia':'Datos de la solicitud'}</h2><p class="small muted mt8">Usa información ficticia durante el recorrido.</p>${ambulance?`<div class="mt24">${info('<strong>Esto es una simulación.</strong> No se solicita ni se despacha una ambulancia. Ante una emergencia real, utiliza los canales de emergencia de tu localidad.','orange')}</div>`:''}<div class="form-grid mt24">${field('Titular del paquete','owner',state.profile.name,'text','readonly wide')}${preventive?fieldSelect('Prestador de preferencia','provider',['Laboratorio Vida Clara','Centro Diagnóstico Alameda','Necesito orientación'],provider):ambulance?field('Ubicación de ejemplo','location','Sede ficticia · Col. Centro, CDMX','text','required wide'):fieldSelect('Tipo de orientación','topic',['Asesoría médica','Reembolso por accidente','Orientación por accidentes','Gastos funerarios','Beneficio de vacunas','Soporte técnico','Otro beneficio'],type)}${field(ambulance?'Fecha de ejemplo':'Fecha de preferencia','date','2026-10-27','date','required min="2026-10-22"')}${fieldSelect('Preferencia de contacto','mode',['En línea','Vía telefónica','Dentro de la plataforma'])}${field('Contacto ficticio','contact',state.profile.phone,'text','required')}${textarea(ambulance?'Referencia de ejemplo':'Comentarios para coordinación','note',ambulance?'Referencia ficticia para demostrar el registro.':'Describe brevemente el apoyo que necesitas, sin datos médicos reales.')}</div><label class="check-row mt24"><input type="checkbox" required><span>Entiendo que esta solicitud es de demostración y no genera una atención real.</span></label><div class="form-actions">${link('S31','Cancelar','btn secondary')}<button type="submit" class="btn">${icon(ambulance?'ambulance':'send')}${ambulance?'Simular solicitud':'Registrar solicitud de ejemplo'}</button></div></form><div class="stack">${serviceAllowance(id)}<section class="card pad">${iconbox(ambulance?'ambulance':preventive?'flask':'chat',ambulance?'orange':'green','big')}<h3 class="mt16">Te acompañamos paso a paso</h3><div class="how-steps mt16"><div class="how-step"><div><strong>Completa la solicitud</strong><p>Cuéntanos lo necesario para coordinar.</p></div></div><div class="how-step"><div><strong>Consulta tu folio</strong><p>Identifica cada solicitud con facilidad.</p></div></div><div class="how-step"><div><strong>Da seguimiento</strong><p>Revisa el estado y agrega comentarios.</p></div></div></div></section>${info('Tu expediente clínico privado permanece separado de la información operativa de las solicitudes.')}</div></div>`}
function coverages(id){
 if(id==='S28')return head('Mis coberturas','Protección y asistencia incluidas en el paquete.',link('S33','Ver documentos','btn secondary','file'))+`<div class="grid3">${[['S29','Reembolso de gastos por accidentes','Hasta $4,000.00 MXN por evento','shield','green'],['S30','Seguro de gastos funerarios','$40,000.00 MXN','leaf','purple'],['S26','Servicio de ambulancia','1 servicio para el trabajador','ambulance','orange']].map(([id,t,d,i,c])=>`<a class="card benefit-card" href="${url(id)}" data-go="${id}">${iconbox(i,c,'big')}<h3 class="mt24">${t}</h3><p>${d}</p><span class="text-link">Consultar beneficio ${icon('arrow')}</span></a>`).join('')}</div>`;
 const funeral=id==='S30',title=funeral?'Seguro de gastos funerarios':'Reembolso de gastos por accidentes',amount=funeral?'$40,000.00':'Hasta $4,000.00';
 return link('S28','Volver a mis coberturas','back','arrow')+head(title,'Paquete Integral de Salud · Protección para el trabajador.')+`<div class="wide-narrow"><section class="card"><div class="detail-hero">${iconbox(funeral?'leaf':'shield',funeral?'purple':'green','big')}<div>${badge('Incluido en el paquete')}<h2 class="mt8">${title}</h2><p>${funeral?'Seguro de apoyo en gastos funerarios.':'Reembolso de gastos derivados de un accidente.'}</p></div></div><div class="pad"><div class="coverage-amount">${amount}<span>MXN${funeral?'':' por evento'}</span></div><h3 class="mt24">${funeral?'Monto del seguro':'Límite de reembolso por evento'}</h3><p class="small muted mt8">${funeral?'Seguro de gastos funerarios por $40,000.00 pesos.':'Reembolso de gastos por accidentes de hasta $4,000.00 pesos por evento.'}</p><div class="mt24">${checkList(['Consulta la documentación y condiciones del beneficio.','Registra una solicitud para recibir orientación.','Integra los soportes solicitados por la coordinación.','Da seguimiento mediante el folio de tu solicitud.'])}</div><div class="mt24">${info('Los montos se muestran conforme al alcance compartido. Esta demostración no procesa reclamaciones ni confirma un reembolso real.')}</div></div></section><div class="stack"><section class="card pad"><div class="mini-label">MI PROTECCIÓN</div><h2>Estamos para acompañarte</h2><div class="details-list" style="padding:15px 0">${dlRow('Titular',h(state.profile.name))}${dlRow('Estado del paquete',badge('Activo'))}${dlRow(funeral?'Seguro de gastos funerarios':'Reembolso por accidente',funeral?'$40,000.00 MXN':'Hasta $4,000.00 MXN')}</div>${link('S24',funeral?'Solicitar orientación':'Solicitar reembolso','btn full','arrow')}${link('S33','Consultar documentación','btn secondary full mt8','file')}</section><section class="card pad"><h3>Seguimiento de tu solicitud</h3><p class="small muted mt8">Consulta el estado, comparte comentarios y organiza los documentos de cada caso.</p>${link('S31','Ver solicitudes','text-link mt24','arrow')}</section></div></div>`;
}
function requestRows(list,company=false){return list.map(r=>`<tr data-search-item data-search-text="${h(r.id+' '+r.type+' '+r.owner)}" data-status="${h(r.status)}"><td><strong>${h(r.id)}</strong><p>${h(r.date)}</p></td>${company?`<td>${h(r.owner)}<p>${h(r.person)}</p></td>`:''}<td>${h(r.type)}</td><td>${status(r.status)}</td><td>${company?h(r.responsible):'Coordinación de salud'}</td><td><button class="text-link" data-request="${h(r.id)}">${company?'Gestionar':'Ver detalle'}${icon('arrow')}</button></td></tr>`).join('')}
function requestsPage(company=false){return head(company?'Solicitudes de colaboradores':'Mis solicitudes',company?'Coordina la atención con visibilidad y seguimiento.':'Cada solicitud tiene un lugar y un siguiente paso.',company?'':link('S24','Nueva solicitud','btn','plus'),company?'GESTIÓN DE BIENESTAR':'TU SALUD, EN UN SOLO LUGAR')+`<div class="grid3 mb16">${[['Abiertas',(company?state.requests:myRequests()).filter(r=>r.status!=='Completada').length,'clipboard','blue'],['En revisión',(company?state.requests:myRequests()).filter(r=>r.status==='En revisión').length,'clock','orange'],['Completadas',(company?state.requests:myRequests()).filter(r=>r.status==='Completada').length,'check','green']].map(([l,v,i,c])=>`<div class="card stat"><div><div class="label">${l}</div><div class="num">${v}</div></div>${iconbox(i,c)}</div>`).join('')}</div><section class="card">${toolbar('Buscar por folio, tipo o colaborador',select('Estado',['Todos los estados','Registrada','En revisión','En proceso','Completada'],'data-filter="status"'))}<div class="table-wrap"><table><thead><tr><th>Folio / fecha</th>${company?'<th>Colaborador</th>':''}<th>Solicitud</th><th>Estado</th><th>Responsable</th><th></th></tr></thead><tbody>${requestRows(company?state.requests:myRequests(),company)}</tbody></table></div><div class="empty-hint">No hay solicitudes que coincidan con tu búsqueda.</div><div class="small muted pad">${(company?state.requests:myRequests()).length} solicitudes · Información de demostración</div></section>`}
function requestDetail(company=false){const r=request();return link(company?'S49':'S31',company?'Volver a la bandeja':'Volver a mis solicitudes','back','arrow')+head(company?'Gestión de solicitud':'Seguimiento de solicitud',h(r.id)+' · '+h(r.type),status(r.status),company?'GESTIÓN DE BIENESTAR':'ESTAMOS CONTIGO')+`<div class="wide-narrow"><div class="stack"><section class="card"><div class="request-identity">${iconbox(r.type.includes('Estudio')?'flask':'clipboard','green')}<div><div class="folio">${h(r.id)} · ${h(r.date)}</div><h2>${h(r.type)}</h2></div></div>${data([['Solicitante',h(r.owner)],['Expediente',h(r.person)],['Responsable',h(r.responsible)],['Estado',status(r.status)],['Comentarios de coordinación',h(r.note||'Sin comentarios adicionales.'),true],...(r.preferredDate?[['Fecha preferida',formatDate(r.preferredDate)]]:[]),...(r.mode?[['Canal preferido',h(r.mode)]]:[]),...(r.provider?[['Prestador',h(r.provider)]]:[]),...(r.location?[['Ubicación de ejemplo',h(r.location),true]]:[])])}</section><section class="card">${cardHead('Historial de seguimiento','Cada paso, con claridad.')}<div class="timeline">${[['Solicitud registrada',r.date,'Tu solicitud quedó guardada en la plataforma.','check'],...(r.status!=='Registrada'?[['Revisión de coordinación','21 oct 2026',r.status==='Completada'?'La solicitud se ha completado.':'La coordinación revisa los datos de tu solicitud.','clipboard']]:[]),...(r.status==='En proceso'?[['Atención en proceso','21 oct 2026','Se está coordinando el siguiente paso.','activity']]:[]),...(r.updates||[])].map(([t,d,n,i])=>`<div class="timeline-item">${iconbox(i||'activity','green')}<div><h4>${h(t)}</h4><time>${h(d)}</time><p>${h(n)}</p></div></div>`).join('')}</div></section><section class="card pad"><h3>Comentarios y archivos</h3><p class="small muted mt8">Comparte únicamente información ficticia de coordinación.</p>${r.comments.map(c=>`<div class="comment"><div class="between"><strong class="small">${h(c.by)}</strong><time class="tiny muted">${h(c.date)}</time></div><p>${h(c.text)}</p></div>`).join('')}${r.files.map(f=>`<div class="comment row">${icon('attach')}<div class="small">${h(f.name)}<p class="tiny muted">Adjunto de demostración · solo se conserva el nombre</p></div></div>`).join('')}<form data-form="comment" class="mt24">${textarea('Agregar un comentario','comment','Escribe un comentario de ejemplo.',true)}<label class="file-upload mt16">${icon('attach')}<span>Adjuntar archivo de prueba</span><input type="file" name="attachment" accept=".pdf,.txt,.png,.jpg" aria-label="Adjuntar archivo de prueba"></label><div class="form-actions"><button class="btn" type="submit">${icon('send')}Agregar comentario</button></div></form></section></div><div class="stack">${company?`<form class="card pad" data-form="request-update"><h2>Actualizar gestión</h2><div class="stack mt24">${fieldSelect('Estado de la solicitud','status',['Registrada','En revisión','En proceso','Completada'],r.status)}${fieldSelect('Responsable','responsible',['Sin asignar','Coordinación de salud','Mesa de atención','Medicina laboral'],r.responsible)}${textarea('Nota de seguimiento','note','Comentario operativo sin información clínica.')}</div><button class="btn full mt24" type="submit">${icon('check')}Guardar actualización</button></form>`:`<section class="card pad"><h3>Tu próximo paso</h3><p class="small muted mt8">${r.status==='Completada'?'Tu solicitud está completada. Revisa los comentarios y documentos relacionados.':'La coordinación revisará tu solicitud. Puedes agregar información o consultar el avance aquí.'}</p><div class="details-list" style="padding:15px 0">${dlRow('Canal','Dentro de la plataforma')}${dlRow('Estado',status(r.status))}</div>${link('S40','Tengo una duda','btn secondary full','help')}</section>`}${info('Solo se comparte información operativa de esta solicitud. Las notas clínicas y recetas permanecen en el expediente personal.')}</div></div>`}
function visibleDocs(){return role==='company'?permittedDocuments(docs,role,state.profile,state.permissions):[...docs,...(state.couponGenerated?[{id:'cupon',name:'Cupón de farmacia · ejemplo',category:'Mi paquete',date:'21 oct 2026',type:'PDF',desc:'Cupón ilustrativo sin valor comercial.',allowed:false}]:[])]}
function documents(){return head('Documentos',role==='company'?'Documentación de la organización y constancias autorizadas.':'Tus documentos de salud y de tu paquete, organizados.',action('download-index','Descargar índice','btn secondary','download'))+tabs([['S33','Todos los documentos'],[role==='company'?'S52':'S35','Centro NOM-035']],'S33')+`<section class="card">${toolbar('Buscar documento',select('Categoría',['Todas las categorías','Mi paquete','Salud','NOM-035'],'data-filter="category"'))}<div class="table-wrap"><table><thead><tr><th>Documento</th><th>Categoría</th><th>Actualizado</th><th>Formato</th><th></th></tr></thead><tbody>${visibleDocs().map(d=>`<tr data-search-item data-search-text="${h(d.name+' '+d.category)}" data-category="${d.category}"><td><div class="row">${iconbox('file',d.category==='NOM-035'?'purple':'blue')}<div><strong>${d.name}</strong><p>${role==='company'?'Documento permitido por rol':'Documento personal de demostración'}</p></div></div></td><td>${d.category}</td><td>${d.date}</td><td>${d.type}</td><td><button class="text-link" data-doc="${d.id}">Abrir documento ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="empty-hint">No encontramos documentos con esos filtros.</div></section><div class="mt24">${info(role==='company'?'El portal empresa solo presenta documentos generales y constancias autorizadas. No incluye recetas ni resultados clínicos privados.':'Todos los archivos descargables son documentos ficticios, marcados como demostración.')}</div>`}
function nomReportCard(){return `<section class="card nom-report"><div class="row">${iconbox('file','purple','big')}<div><div class="mini-label">ANEXO 2 · DOCUMENTACIÓN DEL CONTRATO</div><h2>Reporte de cumplimiento NOM-035-STPS-2018</h2><p class="small muted mt8">Consulta y descarga del reporte adjunto de la organización.</p></div></div><div class="between mt24 wrap"><div>${badge('Reporte original pendiente de adjuntar','orange')}<p class="tiny muted mt8">El ejercicio de bienestar es independiente del reporte de cumplimiento.</p></div><button class="btn secondary" type="button" disabled>${icon('download')}Descargar Anexo 2</button></div></section>`}
const wellnessQuestions=['Tengo claridad sobre mis actividades y responsabilidades.','Cuento con apoyo para organizar mi trabajo.','Puedo hacer pausas durante mi jornada.','Encuentro espacios para expresar mis dudas.','Conozco los canales de apoyo de mi organización.'];
function nom(id){if(id==='S37')return `<div class="success-wrap"><div class="success-icon">${icon('check')}</div><div class="eyebrow">BIENESTAR LABORAL</div><h1>Gracias por compartir</h1><p>Tus respuestas de demostración quedaron guardadas en este navegador. Este ejercicio no genera un diagnóstico ni una evaluación oficial de NOM-035.</p><div class="card pad">${dlRow('Actividad','Ejercicio ilustrativo de bienestar')}${dlRow('Estado',badge('Completado'))}${dlRow('Respuestas','5 de 5')}${dlRow('Fecha','21 de octubre de 2026')}</div><div class="actions">${link('S35','Volver al centro NOM-035','btn','arrow')}</div></div>`;if(id==='S36')return link('S35','Volver al centro NOM-035','back','arrow')+head('Un momento para escucharte','Ejercicio de bienestar de demostración.')+`<div class="wide-narrow"><form class="card pad" data-form="wellness"><div class="between"><h2>¿Cómo te sientes en el trabajo?</h2><span class="small muted" id="question-progress">${Object.keys(state.nom.answers).length} de 5</span></div><div class="progress-bar mt16"><span id="question-bar" style="width:${Object.keys(state.nom.answers).length*20}%"></span></div><div class="mt24">${wellnessQuestions.map((q,i)=>`<fieldset class="question" style="border-left:0;border-right:0;border-top:0;margin:0"><legend class="bold small">${i+1}. ${q}</legend><div class="options">${['Nunca','Casi nunca','A veces','Casi siempre','Siempre'].map((v,n)=>`<label class="radio-option"><input type="radio" name="q${i}" value="${n}" ${String(state.nom.answers['q'+i])===String(n)?'checked':''} required>${v}</label>`).join('')}</div></fieldset>`).join('')}</div><div class="form-actions">${action('save-wellness-draft','Guardar avance','btn secondary','file')}<button type="submit" class="btn">${icon('check')}Guardar respuestas de ejemplo</button></div></form><div class="stack">${info('Estas preguntas son ilustrativas. No corresponden a un instrumento oficial ni permiten acreditar cumplimiento normativo.','orange')}<section class="card pad"><h3>Tu participación cuenta</h3><p class="small muted mt8">La empresa ve participación agregada, sin un visor de tus respuestas individuales.</p><p class="tiny muted mt16">No captures información real de salud ni de otras personas.</p></section></div></div>`;return head('NOM-035-STPS-2018','Documentación de cumplimiento y bienestar laboral.')+nomReportCard()+`<div class="wide-narrow"><section class="card hero"><div class="hero-copy"><span class="hero-label">${icon('leaf')}CENTRO NOM-035</span><h2>Un entorno sano empieza por escucharnos.</h2><p>Conoce los recursos y participa en el ejercicio de bienestar de tu organización.</p>${link(state.nom.complete?'S37':'S36',state.nom.complete?'Ver confirmación':'Abrir ejercicio de bienestar','btn','arrow')}</div>${art()}</section><section class="card pad"><div class="between"><h3>Mi participación</h3>${badge(state.nom.complete?'Completado':'Disponible',state.nom.complete?'green':'blue')}</div><div class="details-list" style="padding:15px 0">${dlRow('Actividad','Ejercicio ilustrativo')}${dlRow('Periodo','Octubre 2026')}${dlRow('Avance',state.nom.complete?'5 de 5 respuestas':Object.keys(state.nom.answers).length+' de 5 respuestas')}</div><div class="progress-bar"><span style="width:${Object.keys(state.nom.answers).length*20}%"></span></div><p class="tiny muted mt16">Este ejercicio no constituye una evaluación normativa oficial.</p></section></div>${section('Recursos para ti','Consulta los documentos de tu organización.')}<div class="grid2"><button class="card quick-action" data-doc="nom" style="text-align:left">${iconbox('file','purple')}<div><h4>Guía de bienestar laboral</h4><p>Material de demostración · PDF</p></div>${icon('chevron')}</button><a class="card quick-action" href="${url('S40')}" data-go="S40">${iconbox('help','blue')}<div><h4>¿Tienes alguna duda?</h4><p>Encuentra orientación sobre la plataforma.</p></div>${icon('chevron')}</a></div><div class="mt24">${info('La documentación y las actividades NOM-035 deberán alinearse al proceso oficial de la empresa antes de una implementación real.','blue')}</div>`}
function profile(id){const p=state.profile;return head('Mi perfil','Tus datos, tu paquete y tus preferencias de privacidad.',id==='S38'?link('S39','Editar perfil','btn','edit'):'')+`<div class="profile-strip">${avatar('ML','pink','xl')}<div><h2>${h(p.name)}</h2><p>${h(p.job)} · ${h(p.company)}</p><div class="row gap8 mt8">${badge('Activo')}<span class="small muted">${p.id}</span></div></div><div class="right"><span class="small muted">${p.package}</span>${badge('Titular','gray')}</div></div>${id==='S39'?`<form class="card pad" data-form="profile"><h2>Datos de contacto</h2><div class="form-grid mt24">${field('Nombre completo','name',p.name,'text','required minlength="5"')}${field('Correo ficticio','email',p.email,'email','required')}${field('Teléfono ficticio','phone',p.phone,'tel','required')}${field('Contacto de apoyo','contact',p.contact,'text','required')}${field('Teléfono del contacto','contactPhone',p.contactPhone,'tel','required')}</div><h3 class="mt32">Autorización de medicina laboral</h3><label class="check-row mt16"><input type="checkbox" name="consent" ${p.consent?'checked':''}><span>Permitir que medicina laboral consulte la constancia preventiva de ejemplo. El permiso no incluye recetas, notas clínicas ni resultados privados.</span></label><div class="mt24">${info('Los cambios se aplican también al portal empresa dentro de esta demostración.')}</div><div class="form-actions">${link('S38','Cancelar','btn secondary')}<button class="btn" type="submit">${icon('check')}Guardar cambios</button></div></form>`:`<div class="grid2"><section class="card">${cardHead('Información personal')}${data([['Correo',h(p.email)],['Teléfono',h(p.phone)],['Empresa',h(p.company)],['Área',h(p.area)],['Contacto de apoyo',h(p.contact)],['Teléfono de apoyo',h(p.contactPhone)]])}</section><div class="stack"><section class="card">${cardHead('Mi paquete')}${data([['Paquete',p.package,true],['Estado',badge('Activo')],['Vigencia ilustrativa','Enero–diciembre 2026']])}</section><section class="card pad"><div class="row">${iconbox('lock','green')}<h3>Tu información, bajo tu control</h3></div><p class="small muted mt16">${p.consent?'Autorizaste la constancia preventiva de ejemplo para medicina laboral.':'No has autorizado el acceso de medicina laboral a tu constancia.'} Tus recetas y notas clínicas son privadas.</p><div class="mt16">${badge(p.consent?'Autorización activa':'Sin autorización',p.consent?'green':'gray')}</div>${link('S39','Revisar autorización','text-link mt24','arrow')}</section></div></div>`}`}
const faqs=[['¿Cómo uso mi Paquete Integral de Salud?','En Beneficios encontrarás los servicios de ejemplo de tu paquete. Abre cada beneficio para revisar el alcance y los pasos de solicitud.'],['¿Cómo agendo una consulta?','En Consultas médicas elige Agendar consulta. Selecciona especialidad, fecha, horario y modalidad. La cita de demostración aparecerá en tu agenda.'],['¿Quién puede ver mi expediente?','Tu expediente personal reúne tus registros privados. En esta demo, la empresa solo ve información laboral y la constancia preventiva que hayas autorizado desde Mi perfil.'],['¿Cómo doy seguimiento a una solicitud?','Abre Solicitudes y selecciona el folio. Ahí puedes consultar el estado, la línea de tiempo y los comentarios compartidos con la coordinación.'],['¿El asistente ofrece diagnósticos?','El asistente de demostración responde dudas de uso y ayuda a navegar. Para temas clínicos, solicita una asesoría con un profesional.'],['¿La solicitud de ambulancia envía una unidad?','Esta Web App es una demostración. El flujo registra un folio ficticio y no envía una unidad de ambulancia ni genera atención médica real.'],['¿El cuestionario acredita NOM-035?','El ejercicio es ilustrativo y no acredita cumplimiento normativo. Permite revisar el flujo de participación y la consulta agregada de la empresa.']];
function help(){return head('¿Cómo podemos ayudarte?','Encuentra respuestas para aprovechar tu paquete con tranquilidad.',link('S41','Abrir asistente','btn','spark'))+`<div class="wide-narrow"><section class="card pad"><h2>Preguntas frecuentes</h2><div class="mt24">${search('Buscar una pregunta')}</div><div class="faq mt16">${faqs.map(([q,a])=>`<details data-search-item data-search-text="${h(q+' '+a)}"><summary>${q}${icon('plus')}</summary><p>${a}</p></details>`).join('')}</div><div class="empty-hint">No hay preguntas que coincidan. Prueba con otra palabra.</div></section><div class="stack"><section class="card pad">${iconbox('spark','green','big')}<h2 class="mt16">Asistente PRESDODUM con IA</h2><p class="small muted mt8">Encuentra el módulo que necesitas, consulta el avance de tus solicitudes y resuelve dudas de uso.</p>${link('S41','Iniciar conversación','btn full mt24','chat')}<p class="tiny muted mt16">Respuestas de demostración · No sustituye una consulta médica.</p></section><section class="card pad"><h3>Soporte técnico</h3><p class="small muted mt8">Puedes registrar una solicitud de soporte de ejemplo y seguirla desde la plataforma.</p>${action('technical-support','Crear solicitud de soporte','btn secondary full mt24','clipboard')}</section></div></div>`}
function companyHome(){const total=people().length,active=people().filter(p=>p.status==='Activo').length,pending=state.requests.filter(r=>r.status!=='Completada').length;return head('Bienestar que se construye en equipo','Una visión clara de la salud y la actividad de '+h(state.config.name)+'.',link('S51','Ver reportes','btn secondary','chart'),'PORTAL EMPRESA · GRUPO HORIZONTE')+`<div class="grid4">${[['Colaboradores',total,'users','green','En la organización de ejemplo'],['Paquetes activos',active,'shield','blue',Math.round(active/total*100)+'% de colaboradores'],['Solicitudes abiertas',pending,'clipboard','orange','Seguimiento operativo'],['Constancias autorizadas',people().filter(p=>p.consent).length,'file','purple','Acceso limitado por permiso']].map(([l,n,i,c,s])=>`<div class="card stat"><div><div class="label">${l}</div><div class="num">${n}</div><div class="trend">${s}</div></div>${iconbox(i,c)}</div>`).join('')}</div><div class="wide-narrow mt24"><section class="card hero"><div class="hero-copy"><span class="hero-label">${icon('users')}BIENESTAR PARA TU EQUIPO</span><h2>Cuidar a las personas.<br>Hacer crecer su bienestar.</h2><p>Acompaña la prevención y coordina los servicios de tu organización.</p>${link('S43','Ver colaboradores','btn','arrow')}</div>${art()}</section><section class="card">${cardHead('Actividad reciente','Información operativa de demostración.')}<a class="list-item" href="${url('S49')}" data-go="S49">${iconbox('clipboard','orange')}<div><h4>${pending} solicitudes en seguimiento</h4><p>Revisa la bandeja de atención.</p></div>${icon('chevron','chev')}</a><a class="list-item" href="${url('S47')}" data-go="S47">${iconbox('flask','green')}<div><h4>Seguimiento preventivo</h4><p>Consulta constancias autorizadas.</p></div>${icon('chevron','chev')}</a><a class="list-item" href="${url('S52')}" data-go="S52">${iconbox('leaf','purple')}<div><h4>Bienestar laboral</h4><p>Explora la participación agregada.</p></div>${icon('chevron','chev')}</a></section></div>${section('Solicitudes que requieren atención','Da continuidad al apoyo para tus colaboradores.',arrowLink('S49','Abrir bandeja'))}<section class="card"><div class="table-wrap"><table><thead><tr><th>Folio / fecha</th><th>Colaborador</th><th>Solicitud</th><th>Estado</th><th>Responsable</th><th></th></tr></thead><tbody>${requestRows(state.requests.filter(r=>r.status!=='Completada').slice(0,3),true)}</tbody></table></div></section><div class="mt24">${info('La empresa consulta actividad operativa y documentos autorizados. El expediente clínico privado pertenece a cada empleado.')}</div>`}
function colleaguePage(){if(!state.permissions.adminDirectory)return head('Colaboradores','Directorio de la organización.')+info('El acceso al directorio está desactivado en los permisos de esta demostración. Puedes cambiarlo en Configuración.','orange')+link('S54','Revisar permisos','btn mt24','settings');return head('Colaboradores','Personas y paquetes de salud de tu organización.',link('S44','Agregar colaborador','btn','plus'),'PORTAL EMPRESA')+`<section class="card">${toolbar('Buscar por nombre, expediente o área',select('Estado',['Todos los estados','Activo','Pendiente'],'data-filter="status"'))}<div class="table-wrap"><table><thead><tr><th>Colaborador</th><th>Área</th><th>Paquete</th><th>Estado</th><th>Autorización</th><th></th></tr></thead><tbody>${people().map(p=>`<tr data-search-item data-search-text="${h(p.name+' '+p.id+' '+p.area)}" data-status="${p.status}"><td><div class="row">${avatar(p.initials,p.color)}<div><strong>${h(p.name)}</strong><p>${p.id}</p></div></div></td><td>${h(p.area)}</td><td>Salud Integral</td><td>${status(p.status)}</td><td>${badge(p.consent?'Constancia autorizada':'Sin autorización',p.consent?'green':'gray')}</td><td><button class="text-link" data-person="${p.id}">Ver perfil ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="empty-hint">No hay colaboradores que coincidan con esos filtros.</div><div class="pad small muted">${people().length} colaboradores · Datos ficticios</div></section>`}
function colleagueDetail(id){const p=person(),authorized=p.consent&&state.permissions.medicalAuthorized;return link('S43','Volver a colaboradores','back','arrow')+head(id==='S46'?'Expediente autorizado':'Perfil de colaborador','Información laboral y alcance permitido por la persona.','','PORTAL EMPRESA')+`<div class="profile-strip">${avatar(p.initials,p.color,'xl')}<div><h2>${h(p.name)}</h2><p>${h(p.area)} · ${h(state.config.name)}</p><div class="row gap8 mt8"><span class="small muted">${p.id}</span>${status(p.status)}</div></div><div class="right">${badge(p.consent?'Autorización registrada':'Sin autorización',p.consent?'green':'gray')}<span class="tiny muted">Solo para medicina laboral</span></div></div>`+tabs([['S45','Resumen del colaborador'],['S46','Expediente autorizado']],id)+(id==='S46'?(authorized?`<div class="notice mb16">${icon('lock')}<div><strong>Acceso limitado a constancias autorizadas</strong><br>No incluye recetas, notas de consulta, respuestas individuales de bienestar ni resultados clínicos.</div></div><section class="card mt24">${cardHead('Documentación autorizada','Alcance de ejemplo registrado por el colaborador.')}${p.id==='PR-00271'?`<button class="list-item full" data-doc="constancia" style="text-align:left">${iconbox('file','green')}<div><h3>Constancia de estudio preventivo</h3><p>08 oct 2026 · Documento sin resultados clínicos</p></div><span class="end text-link">Ver documento ${icon('arrow')}</span></button>`:empty('Sin archivos disponibles','La autorización está registrada; todavía no hay constancias de ejemplo para esta persona.')}</section>`:`<section class="card">${empty('El expediente requiere autorización','No puedes consultar documentos clínicos de esta persona. El acceso debe ser autorizado por el colaborador y estar habilitado para medicina laboral.',link('S45','Volver al resumen','btn secondary','arrow'))}</section>`):`<div class="grid2"><section class="card">${cardHead('Información del paquete')}${data([['Nombre',h(p.name),true],['Área',h(p.area)],['Expediente',p.id],['Paquete','Paquete Integral de Salud',true],['Estado',status(p.status)],['Empresa',h(state.config.name)]])}</section><div class="stack"><section class="card pad"><div class="row">${iconbox('lock','green')}<h3>Alcance de medicina laboral</h3></div><p class="small muted mt16">${p.consent?'El colaborador autorizó la constancia preventiva de demostración.':'El colaborador no ha autorizado documentos para medicina laboral.'}</p>${link('S46',authorized?'Ver expediente autorizado':'Consultar estado de autorización','btn secondary full mt24','eye')}</section><section class="card pad"><h3>Solicitudes del colaborador</h3><p class="small muted mt8">${state.requests.filter(r=>r.person===p.id).length} solicitudes registradas en la demostración.</p>${link('S49','Consultar solicitudes','text-link mt24','arrow')}</section></div></div>`)}
