function drawer(title,subtitle,body,cls=''){return `<div class="overlay-backdrop" data-backdrop><section class="drawer ${cls}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="drawer-head"><div><h2 id="dialog-title">${title}</h2><p>${subtitle}</p></div>${action('close-overlay',icon('close'),'icon-btn','','aria-label="Cerrar panel"')}</header>${body}</section></div>`}
function overlay(){if(current?.id==='S14')return drawer('Agendar consulta','Elige un momento para cuidarte.',`<div class="drawer-body"><div class="notice blue">${icon('calendar')}Cita de demostración · No se reserva atención real.</div><form data-form="appointment" class="mt24"><div class="form-grid">${fieldSelect('Especialidad','specialty',['Medicina general','Medicina interna','Nutrición y bienestar'],providers.find(p=>p.name===provider)?.specialty||'Medicina general')}${fieldSelect('Profesional de la red de ejemplo','doctor',['Dra. Elena Morales','Dr. Andrés Castillo','Dra. Fernanda Ríos'],provider)}${field('Fecha de la cita','date','2026-10-28','date','required min="2026-10-22"')}${fieldSelect('Horario · Hora CDMX','time',['09:00','10:30','12:00','16:00','17:30'])}${fieldSelect('Modalidad','mode',['Videoconsulta','Presencial'])}${textarea('Motivo general · opcional','reason','Ejemplo: revisión de bienestar.')}</div><label class="check-row mt24"><input type="checkbox" required><span>Entiendo que esta agenda solo es de demostración.</span></label><div class="form-actions">${action('close-overlay','Cancelar','btn secondary')}<button class="btn" type="submit">${icon('check')}Confirmar cita de ejemplo</button></div></form></div>`);if(current?.id==='S44')return drawer('Agregar colaborador','Crea un registro ficticio para revisar el flujo.',`<div class="drawer-body"><form data-form="colleague"><div class="form-grid">${field('Nombre completo ficticio','name','','text','required minlength="5"')}${field('Correo de ejemplo','email','','email','required placeholder="nombre@example.com"')}${fieldSelect('Área','area',['Operaciones','Tecnología','Diseño y comunicación','Recursos Humanos','Administración'])}${fieldSelect('Paquete','package',['Paquete Integral de Salud'])}</div><div class="mt24">${info('El registro no crea una cuenta real ni envía una invitación. El acceso a documentos inicia sin autorización.')}</div><div class="form-actions">${action('close-overlay','Cancelar','btn secondary')}<button class="btn" type="submit">${icon('check')}Guardar colaborador de ejemplo</button></div></form></div>`);if(current?.id==='S34'){const d=visibleDocs().find(d=>d.id===selectedDoc);if(!d)return `<div class="overlay-backdrop modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="drawer-head"><h2 id="dialog-title">Documento restringido</h2>${action('close-overlay',icon('close'),'icon-btn','','aria-label="Cerrar documento"')}</header><div class="drawer-body">${info('Este documento es personal y no está disponible para el rol empresa.','orange')}</div></section></div>`;return `<div class="overlay-backdrop modal-backdrop" data-backdrop><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="drawer-head"><div><h2 id="dialog-title">${h(d.name)}</h2><p>Vista previa · Archivo de demostración</p></div>${action('close-overlay',icon('close'),'icon-btn','','aria-label="Cerrar documento"')}</header><div class="drawer-body" style="padding:0"><article class="document-paper">${brand()}<p class="tiny mt16">PAQUETE INTEGRAL DE SALUD · DOCUMENTO FICTICIO</p><h2>${h(d.name)}</h2><p>${h(d.desc)}</p>${data([['Expediente',role==='company'&&d.id!=='constancia'?'Organización de ejemplo':'PR-00271'],['Fecha',d.date],['Titular',role==='company'&&d.id!=='constancia'?h(state.config.name):h(state.profile.name),true]])}<p>Este documento se utiliza para demostrar la consulta, organización y descarga de archivos dentro de PRESDODUM. No tiene validez clínica, contractual ni comercial.</p><div class="doc-stamp">DEMOSTRACIÓN</div></article></div><footer class="preview-toolbar">${action('close-overlay','Cerrar','btn secondary')}${action('doc-download','Descargar PDF de ejemplo','btn','download',`data-doc-id="${d.id}"`)}</footer></section></div>`}if(current?.id==='S41')return drawer(`<span class="row gap8">${icon('spark')}Asistente PRESDODUM</span>`,'Soporte contextual · Respuestas de demostración',`<div class="chat-body" id="chat-messages">${chat.map(c=>`<div class="chat-bubble ${c.from==='user'?'user':''}">${h(c.text)}${c.to?link(c.to,c.label||'Abrir sección','text-link','arrow'):''}</div>`).join('')}<div class="chat-suggestions">${['Mis beneficios','Agendar consulta','Mi solicitud','Documentos'].map(t=>`<button data-chat-suggestion="${t}">${t}</button>`).join('')}</div></div><form class="chat-form" data-form="chat"><input type="text" name="message" required placeholder="¿En qué puedo ayudarte?" aria-label="Escribir al asistente" maxlength="500"><button class="btn" type="submit" aria-label="Enviar al asistente">${icon('send')}</button></form><p class="chat-note">Asistente de demostración. No ofrece diagnósticos ni sustituye una consulta médica.</p>`,'chat-panel');return ''}
const renderers={M01:access,M02:dashboard,M03:health,M04:clinical,M05:consultations,M06:medications,M07:benefits,M08:benefitDetail,M09:network,M10:requestForm,M11:coverages,M12:coverages,M13:()=>requestsPage(false),M14:()=>requestDetail(false),M15:documents,M16:nom,M17:profile,M18:help,M19:companyHome,M20:colleaguePage,M21:colleagueDetail,M22:occupational,M23:id=>id==='S49'?requestsPage(true):requestDetail(true),M24:reports,M25:settings};
function render(){const path=location.hash.slice(1)||'/empleado/inicio';current=screens.find(s=>s.path===path);if(path.startsWith('/empresa')||current?.id==='S02')role='company';else if(path.startsWith('/empleado')||current?.id==='S01')role='employee';sessionStorage.setItem('presdodum.role',role);notices=false;mobile=false;document.title='PRESDODUM · '+(current?.name||'Mapa del producto');const content=current?renderers[current.m](current.id):productMap();$('#app').innerHTML=current?.m==='M01'?content:shell(content);$('#overlay').innerHTML=overlay();document.body.style.overflow=$('#overlay').innerHTML?'hidden':'';if($('#overlay').innerHTML){queueMicrotask(()=>{$('#overlay button')?.focus();$('#chat-messages')?.scrollTo(0,$('#chat-messages').scrollHeight)})}const report=$('[data-report-period]');if(report)report.value=reportPeriod;}
function filterItems(){const q=normal($('[data-search]')?.value||'');const filters=[...document.querySelectorAll('[data-filter]')];const items=[...document.querySelectorAll('[data-search-item]')];let visible=0;items.forEach(el=>{const match=normal(el.dataset.searchText||el.textContent).includes(q)&&filters.every(f=>f.value.startsWith('Todo')||f.value.startsWith('Toda')||el.dataset[f.dataset.filter]===f.value);el.hidden=!match;if(match)visible++});const hint=$('.empty-hint');if(hint)hint.style.display=visible===0?'block':'none'}
const normal=t=>String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function downloadFile(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csvDownload(name,headers,rows){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';downloadFile(name,'\uFEFF'+[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function downloadDoc(id){const allowed=visibleDocs().find(d=>d.id===id);if(!allowed){toast('Este documento no está disponible para este rol.');return}const a=document.createElement('a');a.href='archivos/'+id+'.pdf';a.download='PRESDODUM_'+id+'_ejemplo.pdf';document.body.append(a);a.click();a.remove();toast('Descarga del documento de ejemplo iniciada.')}
function addChat(message){chat.push({from:'user',text:message});const msg=normal(message);let text,to,label;if(role==='company'){if(/colaborador|empleado/.test(msg)){text='El directorio te permite consultar perfiles y revisar si hay una autorización de medicina laboral. Los registros son ficticios.';to='S43';label='Ver colaboradores'}else if(/nom|bienestar|cuestionario/.test(msg)){text='En NOM-035 puedes revisar la participación agregada y los documentos de apoyo. No se muestran respuestas individuales ni una evaluación normativa oficial.';to='S52';label='Ver participación'}else if(/documento|descargar/.test(msg)){text='Documentos reúne los archivos generales de la empresa y las constancias autorizadas disponibles. Las recetas y notas privadas no se incluyen.';to='S33';label='Abrir documentos'}else if(/reporte|indicador/.test(msg)){text='Los reportes muestran actividad agregada y permiten filtrar el periodo y exportar un CSV de ejemplo.';to='S51';label='Ver reportes'}else{text='Puedo orientarte sobre colaboradores, medicina laboral, solicitudes, reportes y documentos. En Solicitudes puedes actualizar responsables y estados de ejemplo.';to='S49';label='Abrir solicitudes'}}else if(/dolor|sintoma|dosis|diagnost|tratamiento|tomar|enfermedad/.test(msg)){text='Puedo ayudarte con la plataforma. Para revisar síntomas, tratamientos o decisiones de salud, solicita orientación con un profesional. No introduzcas datos médicos reales en esta demo.';to='S24';label='Solicitar asesoría'}else if(/ambulancia|emergencia/.test(msg)){text='El flujo de ambulancia es una simulación y no despacha una unidad. Ante una emergencia real, utiliza los canales de emergencia de tu localidad.';to='S26';label='Ver simulación de ambulancia'}else if(/receta|medicamento|farmacia/.test(msg)){text='Tus recetas están en Mi salud. Si buscas el beneficio de farmacia, puedes generar un cupón de demostración desde Beneficios.';to='S16';label='Ver mis recetas'}else if(/beneficio|paquete|descuento|vacuna/.test(msg)){text='Tu Paquete Integral de Salud está activo. Puedes explorar prevención, vacunas, red médica, estudios, farmacia y asesorías. Los alcances son ilustrativos.';to='S17';label='Explorar beneficios'}else if(/cita|consulta|agend/.test(msg)){text='Para agendar, selecciona especialidad, profesional, fecha y modalidad. La cita de ejemplo aparecerá en Consultas médicas.';to='S14';label='Agendar consulta'}else if(/solicitud|folio|seguimiento/.test(msg)){const r=request();text='La solicitud '+r.id+' de '+r.type+' está en estado «'+r.status+'». Abre el detalle para consultar el historial y agregar un comentario de coordinación.';to='S32';label='Ver seguimiento'}else if(/documento|descargar|archivo/.test(msg)){text='En Documentos puedes buscar, previsualizar y descargar los PDF ficticios de tu paquete. Todos están marcados como demostración.';to='S33';label='Abrir documentos'}else if(/nom|cuestionario|bienestar/.test(msg)){text='El centro NOM-035 contiene documentos y un ejercicio ilustrativo de bienestar. El ejercicio no constituye una evaluación normativa oficial.';to='S35';label='Ir al centro NOM-035'}else if(/privacidad|autoriz|expediente/.test(msg)){text='Tus recetas y notas clínicas son privadas. Puedes revisar o retirar la autorización de la constancia preventiva de ejemplo desde Mi perfil.';to='S38';label='Revisar mi perfil'}else if(/cobertura|accidente|funerario/.test(msg)){text='En Coberturas puedes conocer los ejemplos de asistencia por accidentes, gastos funerarios y ambulancia. Las condiciones deberán validarse con el contrato.';to='S28';label='Ver coberturas'}else{text='Estoy aquí para guiarte. Puedes preguntarme por beneficios, citas, solicitudes, documentos o el uso de tu expediente. También tienes respuestas en el centro de ayuda.';to='S40';label='Abrir centro de ayuda'}chat.push({from:'bot',text,to,label});$('#overlay').innerHTML=overlay();$('#chat-messages')?.scrollTo(0,$('#chat-messages').scrollHeight);$('#overlay input[name="message"]')?.focus()}
const forms={
 appointment(form,data){state.appointments.unshift({id:'CIT-'+String(285+state.appointments.length).padStart(4,'0'),date:data.get('date'),time:data.get('time'),doctor:data.get('doctor'),specialty:data.get('specialty'),mode:data.get('mode'),status:'Confirmada',reason:data.get('reason')||'Revisión de bienestar'});persist();go('S12');toast('Tu cita de ejemplo está confirmada y aparece en tu agenda.')},
 request(form,data){const type=form.dataset.requestType;const next=Math.max(1048,...state.requests.map(r=>Number(r.id.split('-')[1])||0))+1;const r={id:'SOL-'+next,type:type==='Asesoría médica'?data.get('topic')||type:type,date:'21 oct 2026',status:'Registrada',owner:state.profile.name,person:'PR-00271',note:data.get('note')||'Solicitud de demostración.',responsible:'Sin asignar',comments:[],files:[],preferredDate:data.get('date'),mode:data.get('mode'),provider:data.get('provider')||'',contact:data.get('contact')||'',location:data.get('location')||''};state.requests.unshift(r);selectedRequest=r.id;persist();go('S27')},
 comment(form,data){const r=request();r.comments.push({by:role==='company'?state.config.contact:state.profile.first,date:'21 oct 2026',text:data.get('comment')});const file=data.get('attachment');if(file?.name)r.files.push({name:file.name,size:file.size});persist();render();toast('Comentario de ejemplo agregado al seguimiento.')},
 'request-update'(form,data){const r=request(),old=r.status;r.status=data.get('status');r.responsible=data.get('responsible');r.updates=r.updates||[];r.updates.push(['Gestión actualizada','21 oct 2026',old+' → '+r.status+'. '+(data.get('note')||'Responsable: '+r.responsible),'activity']);persist();go('S49');toast('Solicitud actualizada. El cambio también se refleja en el portal empleado.')},
 wellness(form,data){const answers={};for(let i=0;i<5;i++)answers['q'+i]=data.get('q'+i);state.nom={complete:true,answers};persist();go('S37')},
 profile(form,data){for(const k of ['name','email','phone','contact','contactPhone'])state.profile[k]=data.get(k).trim();state.profile.first=state.profile.name.split(' ')[0];state.profile.consent=data.get('consent')==='on';for(const r of myRequests())r.owner=state.profile.name;persist();go('S38');toast('Tu perfil y autorización se actualizaron.')},
 colleague(form,data){const name=data.get('name').trim();state.people.push({id:'PR-'+String(277+state.people.length).padStart(5,'0'),name,email:data.get('email'),area:data.get('area'),initials:name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase(),status:'Activo',consent:false,color:'blue'});persist();go('S43');toast('Colaborador ficticio agregado al directorio.')},
 config(form,data){for(const k of ['name','contact','email','phone'])state.config[k]=data.get(k).trim();state.profile.company=state.config.name;persist();render();toast('Configuración guardada en este navegador.')},
 permissions(form,data){for(const k of Object.keys(state.permissions))state.permissions[k]=data.get(k)==='on';persist();render();toast('Permisos de demostración actualizados.')},
 notifications(form,data){for(const k of Object.keys(state.notifications))state.notifications[k]=data.get(k)==='on';persist();render();toast('Preferencias guardadas. No se envían avisos externos.')},
 recovery(){go('S04')},
 chat(form,data){addChat(data.get('message').trim())}
};
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(!form.checkValidity()){form.reportValidity();return}forms[form.dataset.form]?.(form,new FormData(form))});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]'))filterItems()});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter]'))filterItems();if(e.target.closest('[data-form=appointment]')){const form=e.target.form;if(e.target.name==='specialty')form.elements.doctor.value=providers.find(p=>p.specialty===e.target.value)?.name||'Dra. Elena Morales';if(e.target.name==='doctor')form.elements.specialty.value=providers.find(p=>p.name===e.target.value)?.specialty||'Medicina general';}if(e.target.matches('[data-report-period]')){reportPeriod=e.target.value;render()}if(e.target.closest('[data-form="wellness"]')){state.nom.answers[e.target.name]=e.target.value;persist();const n=Object.keys(state.nom.answers).length;$('#question-progress').textContent=n+' de 5';$('#question-bar').style.width=n*20+'%'}});
document.addEventListener('click',e=>{const el=e.target.closest('a,button,[data-backdrop]');if(!el)return;if(el.classList.contains('skip')){e.preventDefault();$('#content')?.focus();return}if(el.dataset.backdrop!==undefined&&e.target===el){closeOverlay();return}if(el.dataset.portal){role=el.dataset.portal;sessionStorage.setItem('presdodum.role',role);go(role==='company'?'S42':'S05');return}if(el.dataset.doc){selectedDoc=el.dataset.doc;go('S34');return}if(el.dataset.request){selectedRequest=el.dataset.request;go(role==='company'?'S50':'S32');return}if(el.dataset.person){selectedPerson=el.dataset.person;go(el.dataset.personTo||'S45');return}if(el.dataset.provider){provider=el.dataset.provider;go('S23');return}if(el.dataset.mapMode){mapMode=el.dataset.mapMode;render();return}if(el.dataset.chatSuggestion){addChat(el.dataset.chatSuggestion);return}if(el.dataset.go){e.preventDefault();const id=el.dataset.go;if(id==='S24'){requestContext=current?.id==='S29'?'Reembolso por accidente':current?.id==='S30'?'Gastos funerarios':current?.id==='S18'?'Beneficio de vacunas':''}if(id==='S34')selectedDoc=current?.id==='S11'?'resultado':current?.id==='S10'?'receta':'paquete';if(id==='S41'||['S14','S34','S44'].includes(id))previous=current?.id||'MAP';go(id);return}switch(el.dataset.action){case 'menu':mobile=!mobile;$('.sidebar')?.classList.toggle('open',mobile);break;case 'assistant':previous=current?.id||(role==='company'?'S42':'S05');go('S41');break;case 'close-overlay':closeOverlay();break;case 'notifications':notices=!notices;$('#app').innerHTML=shell(current?renderers[current.m](current.id):productMap());break;case 'coupon':state.couponGenerated=true;persist();selectedDoc='cupon';go('S34');toast('Cupón ficticio generado. No tiene valor comercial.');break;case 'doc-download':downloadDoc(el.dataset.docId||selectedDoc);break;case 'export-health':csvDownload('PRESDODUM_informe_personal.csv',['Indicador de ejemplo','Valor'],[['Expediente',state.profile.id],['Titular',state.profile.name],['Registros de historia clínica',4],['Recetas registradas',1],['Documentos personales',6],['Autorización laboral',state.profile.consent?'Activa':'No autorizada']]);toast('Informe personal de ejemplo generado.');break;case 'download-index':csvDownload('PRESDODUM_indice_documentos.csv',['Documento','Categoría','Fecha','Formato'],visibleDocs().map(d=>[d.name,d.category,d.date,d.type]));toast('Índice de documentos exportado.');break;case 'appointment-details':{const details=document.getElementById('indications-'+el.dataset.id);if(details){details.hidden=!details.hidden;el.setAttribute('aria-expanded',String(!details.hidden));}break;}case 'cancel-appointment':{const a=state.appointments.find(a=>a.id===el.dataset.id);if(a)a.status='Cancelada';persist();render();toast('Cita de ejemplo cancelada. Puedes agendar una nueva.');break}case 'save-wellness-draft':persist();toast('Tu avance quedó guardado en este navegador.');break;case 'export-report':if(!state.permissions.adminReports){toast('La exportación está desactivada en los permisos de demostración.');break}csvDownload('PRESDODUM_reporte_bienestar.csv',['Periodo','Estado','Cantidad de ejemplo'],['Registrada','En revisión','En proceso','Completada'].map(s=>[reportPeriod,s,reportRequests().filter(r=>r.status===s).length]));toast('Reporte agregado de ejemplo exportado.');break;case 'export-nom':csvDownload('PRESDODUM_participacion_bienestar.csv',['Periodo','Colaboradores ficticios','Participaciones de ejemplo','Evaluación oficial'],[['Octubre 2026',people().length,Math.min(people().length,3+(state.nom.complete?1:0)),'No aplica: ejercicio ilustrativo']]);toast('Participación agregada exportada.');break;case 'technical-support':requestContext='Soporte técnico';role='employee';go('S24');break}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#overlay').innerHTML)closeOverlay();else if(notices){notices=false;render()}else if(mobile){mobile=false;$('.sidebar')?.classList.remove('open')}}if(e.key==='Tab'&&$('#overlay').innerHTML){const nodes=[...$('#overlay').querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(n=>!n.disabled&&n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
window.addEventListener('storage',event=>{if(event.key==='presdodum.v1'&&event.newValue){try{state=JSON.parse(event.newValue);render()}catch{}}});
if(!location.hash)history.replaceState(null,'','#/empleado/inicio');render();
